1	// tuning/_tp8_scratch_pybind.cu — NON-COMMITTED scratch wiring (the multiopt-runner
2	// style) for the TP8 + in-kernel device-NVSHMEM all-reduce flagship run.
3	//
4	// WHY: the committed mega_decoder_real_adamw_tc.cu pybind `tc_train_step` calls
5	// launch_fused_decoder_megakernel_tc<OptId::AdamW>() — the SingleGPU template,
6	// tp_size=1, NO CommCtx — so it NEVER fires the in-kernel TP all-reduce. The TP
7	// dispatch (ParTP8 + dec_tc_ensure_tp_sym_heap + CommCtx + the device
8	// NvshmemTransport) lives in the launcher's 18-arg mega_decoder_real_adamw_tc(...,
9	// int tp_size) (mega_decoder_real_adamw_tc_launcher.cu:128, the `tp_size==8` arm).
10	// That arm is reached only via a caller passing tp_size=8.
11	//
12	// THIS scratch TU #includes the committed launcher .cu (so it gets the 18-arg
13	// TP-aware function verbatim — NO committed source edited) and exposes ONE pybind
14	// entry `tc_train_step_tp8(params, tokens, targets, state, scalars..., step, ncta)`
15	// that calls that function with tp_size=8. Built with -DSG_HAS_NVSHMEM=1 -rdc=true
16	// + device-linked against libnvshmem_device.a, so:
17	//   * the launcher arm's nvshmem_malloc / nvshmem_team_my_pe resolve to the SAME
18	//     process-global NVSHMEM world the sg_nvshmem_bringup pybind already nvshmem_init'd
19	//     (same physical libnvshmem_host.so.3 in the process);
20	//   * the megakernel's device-side make_transport_from_comm<ParTP8>() returns the
21	//     REAL NvshmemTransport (tp_transport.cuh:291), whose peer() uses nvshmem_ptr
22	//     over NVLink — the in-kernel device all-reduce, NOT loopback.
23	//
24	// The launcher's anonymous-namespace DecTcLauncherScratch + dec_tc_ensure_tp_sym_heap
25	// come in via the #include; we DO NOT redefine them.
26	
27	#include <torch/extension.h>
28	#include <c10/cuda/CUDAStream.h>
29	#include <c10/cuda/CUDAException.h>
30	#include <cuda_runtime.h>
31	#include <cstdint>
32	#include <vector>
33	
34	// Pull in the committed TP-aware launcher verbatim (gives us the 18-arg
35	// ::sg::fused::sm90::mega_decoder_real_adamw_tc + DecTcLauncherScratch +
36	// dec_tc_ensure_tp_sym_heap + the whole megakernel header). Compiled as ONE TU.
37	#include "csrc/fused/sm_90/mega_decoder_real_adamw_tc_launcher.cu"
38	
39	using ::sg::fused::sm90::kDecTotalElems;
40	using ::sg::fused::sm90::kDecNumTensors;
41	namespace dec = ::sg::fused::sm90::dec;
42	
43	// Expose the built-in flagship dims so the harness can assert the layout swap took.
44	static int64_t cfg_D()      { return (int64_t)dec::kD; }
45	static int64_t cfg_LAYERS() { return (int64_t)dec::kLayers; }
46	static int64_t cfg_TOTAL()  { return (int64_t)kDecTotalElems; }
47	static int64_t cfg_NUMT()   { return (int64_t)kDecNumTensors; }
48	
49	// tc_train_step_tp8 — one Fork-B TC step through the TP8 in-kernel-allreduce path.
50	//   params  [total] fp32  (the FULL flat decoder blob, replicated per rank — the
51	//           kernel reads its TP-owned column/row shards via the layout; the host
52	//           passes the whole blob and the kTPComm GEMM tiles index the rank's
53	//           kTP slice. params updated in place by the P3 AdamW tail.)
54	//   tokens  [B,kSeq] int32 ; targets [B] int32  (TP-replicated batch)
55	//   state   [>= 4*total + 8] fp32  ([m | v | extra | loss | ...]) — AdamW uses
56	//           m,v; loss_out points at state + 3*total.
57	// Returns {loss (cpu f32 scalar), grad [total] fp32 (the rank's reduced grad)}.
58	static std::vector<torch::Tensor> tc_train_step_tp8(
59	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
60	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
61	        double weight_decay, double bc1, double bc2, int64_t step,
62	        int64_t ncta_cap) {
63	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
64	    TORCH_CHECK(params.numel() == kDecTotalElems,
65	                "params must be the flat decoder blob (", kDecTotalElems, ")");
66	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
67	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
68	    const int B = (int)targets.numel();
69	    TORCH_CHECK(tokens.numel() == (int64_t)B * dec::kSeq, "tokens must be [B,kSeq]");
70	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0");
71	    const int64_t total = kDecTotalElems;
72	    // The launcher binds loss_out = state + 3*total and writes [param_init|...]
73	    // AFTER it for staged opts; AdamW only needs m,v,extra + the loss slot, so
74	    // require >= 3*total + 1. Give a margin (4*total + 8) to be safe.
75	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
76	                && state.numel() >= 3 * total + 1,
77	                "state must be contiguous fp32 [>= 3*total + 1]");
78	
79	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
80	
81	    // Persistent grid-barrier counters (cached per device inside the launcher's
82	    // DecTcLauncherScratch; ctx fields get re-pointed there by the launcher, so the
83	    // values we pass for g_* are placeholders the launcher overwrites). We still
84	    // must pass a valid PersistentContext POD.
85	    static torch::Tensor s_gn, s_ga, s_gg;
86	    if (!s_gn.defined()) {
87	        auto oi = torch::dtype(torch::kInt32).device(params.device());
88	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
89	    }
90	    ::sg::fused::PersistentContext ctx{
91	        s_gn.data_ptr<int>(),
92	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
93	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
94	        kDecNumTensors, 0u};
95	
96	    // loss_out lives in the caller's state buffer at state + 3*total (the launcher's
97	    // dispatch loss_slot convention).
98	    float* state_p   = state.data_ptr<float>();
99	    float* loss_out  = state_p + 3 * total;
100	
101	    // FusedScalars POD (AdamW reads lr/beta1/beta2/eps/wd/bc1/bc2; the rest inert).
102	    ::sg::fused::sm90::FusedScalars scalars;
103	    scalars.lr = (float)lr; scalars.beta1 = (float)beta1; scalars.beta2 = (float)beta2;
104	    scalars.eps = (float)eps; scalars.wd = (float)weight_decay;
105	    scalars.bc1 = (float)bc1; scalars.bc2 = (float)bc2;
106	
107	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
108	
109	    // THE TP8 call: tp_size=8 → the launcher's ParTP8 arm (dec_tc_ensure_tp_sym_heap
110	    // + CommCtx + the device NvshmemTransport in-kernel all-reduce).
111	    cudaError_t err = ::sg::fused::sm90::mega_decoder_real_adamw_tc(
112	        ctx, params.data_ptr<float>(),
113	        tokens.data_ptr<int>(), targets.data_ptr<int>(), B,
114	        state_p, grad.data_ptr<float>(), /*workspace_unused=*/nullptr, loss_out,
115	        /*sizes=*/nullptr, /*offsets=*/nullptr,
116	        (float)lr, (int)step, scalars, stream, (int)ncta_cap,
117	        /*opt_id=*/(int)::sg::fused::sm90::OptId::AdamW, /*tp_size=*/8);
118	    TORCH_CHECK(err == cudaSuccess,
119	                "TP8 TC megakernel launch failed: ", cudaGetErrorString(err));
120	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
121	
122	    // loss_out holds the reduced NLL the kernel wrote (state + 3*total).
123	    auto loss_dev = state.narrow(0, 3 * total, 1).clone();
124	    return {loss_dev.to(torch::kCPU), grad};
125	}
126	
127	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
128	    m.doc() = "TP8 scratch pybind: in-kernel device-NVSHMEM all-reduce flagship step.";
129	    m.def("tc_train_step_tp8", &tc_train_step_tp8,
130	          py::arg("params"), py::arg("tokens"), py::arg("targets"), py::arg("state"),
131	          py::arg("lr"), py::arg("beta1"), py::arg("beta2"), py::arg("eps"),
132	          py::arg("weight_decay"), py::arg("bc1"), py::arg("bc2"), py::arg("step"),
133	          py::arg("ncta_cap"),
134	          "one Fork-B TC step via the ParTP8 in-kernel NVSHMEM all-reduce path");
135	    m.attr("D")      = cfg_D();
136	    m.attr("LAYERS") = cfg_LAYERS();
137	    m.attr("TOTAL")  = cfg_TOTAL();
138	    m.attr("NUMT")   = cfg_NUMT();
139	}
