2107	template <class Par = ::sg::fused::par::SingleGPU,
2108	          class Transport = ::sg::fused::sm90::tp::LoopbackTransport>
2109	__device__ float dectc_forward_tile_impl(
2110	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, bool active,
2111	        const DecActs& acts,
2112	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
2113	        const int* __restrict__ tgt_ids,
2114	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
2115	        const Transport& tr, const ::sg::fused::GridBarrier& bar,
2116	        int64_t slot_pub, int64_t slot_red,
2117	        unsigned long long* pipeBars = nullptr) {
2118	    // On the kTPComm path an inactive round still must reach every rendezvous;
2119	    // the GEMM/elementwise work is skipped (nrows==0) but the rendezvous calls
2120	    // at ①/② below run unconditionally (the §1 lockstep invariant).
2121	    (void)active; (void)slot_red;
2122	    const int nsamp = nrows / dec::kSeq;
2123	    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
2124	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
2125	        const int r = idx / dec::kD, j = idx % dec::kD;
2126	        const int g = g0 + r;
2127	        const int tid = tok_ids[g];
2128	        const int sp = g % dec::kSeq;            // position within the sample
2129	        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
2130	        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
2131	    }
2132	    __syncthreads();
2133	
2134	    for (int li = 0; li < dec::kLayers; ++li) {
2135	        const DecWeights::Layer& L = w.layer[li];
2136	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
2137	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
2138	        // COLUMN(QKV)-parallel on kTPComm: rank owns 3d/P out columns (§6 NOTE).
2139	        const int qkv_nout = Par::kTPComm ? (3 * dec::kD) / Par::kTP : 3 * dec::kD;
2140	        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, wb.in_w[li], sc.qkv[li], dec::kD, qkv_nout, sA, sB, pipeBars);
2141	        __syncthreads();
2142	        // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
2143	        // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
2144	        for (int idx = threadIdx.x; idx < nrows * qkv_nout; idx += blockDim.x) {
2145	            const int j = idx % qkv_nout;
2146	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
2147	            sc.qkv[li][idx] = __float2bfloat16(v);
2148	        }
2149	        __syncthreads();
2150	        // attention → ctx (work fp32) + attn[li] weights. HEAD-LOCALIZED on the
2151	        // kTPComm path: the col-parallel qkv is the rank's [q|k|v]_own shard
2152	        // (stride 3*Dloc, Hloc=kHeads/P heads); ctx is the rank's own [nrows,Dloc]
2153	        // (recombined to full width by the row-parallel out_proj all-reduce ① below).
2154	        // tp_kernel.md §6/§12 head-localization NOTE. SingleGPU path uses the
