2450	        // above), qkv is the [q|k|v]_own shard (stride 3*Dloc, Hloc heads), and the
2451	        // produced dqkv (work2) is the rank's own [nrows,3*Dloc] (==qkv_nout) fed to
2452	        // the column-parallel in_proj dX reduce ①' below. SingleGPU uses the
2453	        // byte-identical dectc_attn_bwd_tile (this branch folds away there).
2454	        if constexpr (!Par::kTPComm) {
2455	            dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
2456	        } else {
2457	            const int Dloc = dec::kD / Par::kTP;          // local q/k/v block width
2458	            const int Hloc = dec::kHeads / Par::kTP;      // local whole heads (0 if kHeads%P!=0)
2459	            dectc_attn_bwd_tile_tp(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc, Hloc, Dloc);
2460	        }
2461	        for (int idx = threadIdx.x; idx < nrows * qkv_nout; idx += blockDim.x)
2462	            acts.dY_qkv[li][(int64_t)g0 * qkv_nout + idx] = __float2bfloat16(work2[idx]);
2463	        __syncthreads();
2464	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
2465	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
2466	        if constexpr (!Par::kTPComm) {
2467	            dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, wb.in_wT[li],
2468	                                               sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB, pipeBars);  // dx_in_attn
2469	        } else {
2470	            // COLUMN(QKV)-parallel in_proj: in_wT[li] is the rank's [3d/P, d] qkv
2471	            // col-shard's transpose; dY_qkv is the rank's own [nrows, 3d/P] (the
2472	            // 3-block q|k|v own-rows concatenated). The dX is a PARTIAL → publish
2473	            // [nrows,d] → reduce → sc.work (①' of design §5.1). Then the residual
2474	            // add `sc.dh[idx] += sc.work[idx]` below runs unchanged.
2475	            const int Noutloc = (3 * dec::kD) / tr.n_pes();
2476	            if (active) {
2477	                ::sg::fused::sm90::tp::tp_colparallel_dx_partial_tile<SG_TUNED_TILE_N>(
2478	                    tr, slot_pub,
2479	                    /*dYown=*/ acts.dY_qkv[li] + (int64_t)g0 * Noutloc, wb.in_wT[li],

2480	                    /*Kin=*/ dec::kD, /*Nout_local=*/ Noutloc, sA, sB);
2481	            }
2482	            tr.rendezvous(bar);
2483	            ::sg::fused::sm90::tp::tp_allreduce_sum_fixed_order(
2484	                tr, slot_pub, sc.work, (int64_t)nrows * dec::kD, threadIdx.x, blockDim.x);
2485	            tr.rendezvous(bar);
2486	        }
2487	        __syncthreads();
2488	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
2489	            sc.dh[idx] += sc.work[idx];
2490	        __syncthreads();
2491	    }
2492	
2493	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
2494	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
2495	    __syncthreads();
2496	}
