2557	// ════════════════════════════════════════════════════════════════════════
2558	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
2559	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
2560	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
2561	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
2562	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
2563	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
2564	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
2565	//
2566	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
2567	//  the contraction length K (T for per-position weights, B for the head).
2568	// ════════════════════════════════════════════════════════════════════════
2569	struct DecDwSpec {
2570	    const __nv_bfloat16* dY;   // [K, Nout]
2571	    const __nv_bfloat16* X;    // [K, Kin]
2572	    int Nout; int Kin; int K;
2573	    int grad_off;              // element offset of this weight in `grad`
2574	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
2575	    int bias_off;              // element offset of the bias in `grad`
2576	#if SG_TUNED_DEC_DW_STAGE
2577	    // CONTIGUOUS-TRANSPOSE staging scratch (SG_TUNED_DEC_DW_STAGE=1 only). These
2578	    // three pointers exist ONLY when the macro is set, so the scalar-default
2579	    // struct (and therefore DecTcSmem's smem footprint + the kernel's register
2580	    // allocation) is BYTE-IDENTICAL to every shipped build (PTX-verified). dYt =
2581	    // K-major TRANSPOSE of dY, shape [Mpad, K] row-major (dYt[m,k] = dY[k,m]); Xt
2582	    // = [Kin, K] (Xt[n,k] = X[k,n]). Rows are K-CONTIGUOUS + 16B-aligned (K is a
2583	    // multiple of kWgmmaAtomK=16 ⇒ 8 bf16), so DecGmemTileSrcA/B read them with
2584	    // the proven 16B cp.async ring instead of the 2-byte transposed-strided
2585	    // gather. Filled ONCE per step by dectc_dw_transpose_operands (a pure bf16
2586	    // copy — no math → parity-safe).
2587	    __nv_bfloat16* dYt;        // [Mpad, K] (transposed dY) — null unless active
2588	    __nv_bfloat16* Xt;         // [Kin,  K] (transposed X)  — null unless active
2589	    int64_t t_off;             // element offset of (dYt|Xt) base in the dW-T scratch
2590	#endif
2591	};
2592	
2593	// Number of dW specs: 4 per layer (in_proj, out_proj, ff0, ff2) + 1 head.out.
2594	//   = 4*L + 1  (= 9 at L=2, the original spec[9]; = 193 at the flagship L=48).
2595	// This is the compile-time bound for EVERY DecDwSpec array (the DecTcSmem member,
2596	// every spec[] signature/local, the dW phase loops, the bias prefix). At L=2 it
2597	// is exactly 9 → the spec arrays + their stack/smem footprint are byte-identical.
2598	constexpr int kDecNumDwSpecs = 4 * dec::kLayers + 1;
2599	
2600	// ── CONTIGUOUS-TRANSPOSE dW scratch geometry (SG_TUNED_DEC_DW_STAGE=1). The 9
2601	//    weights' transposed operands (dYt[Nout,K] + Xt[Kin,K]) are packed into ONE
2602	//    contiguous bf16 region. Per weight s the block is (Nout_s + Kin_s)·K_s bf16:
2603	//    dYt at base+0, Xt at base+Nout_s·K_s. The SAME running-offset walk is used
2604	//    by the host workspace sizer (dec_tc_dw_transpose_floats) and the device spec
2605	//    builder (dectc_build_dw_specs) so the carve and the kernel agree exactly. K_s
2606	//    is T for the 8 layer weights, B for the head — both multiples of kWgmmaAtomK
2607	//    in every (B, kSeq) the bench/production use (so each transposed ROW is 16B-
2608	//    aligned, the cp.async-ring chunk16 requirement). Returns bf16 ELEMENTS. ──
2609	// Per-weight transpose-block bf16 elems: dYt is row-padded to a multiple of 64
2610	// (the engine's m64 atom) so the cp.async ring's UNGUARDED A-row reads (it has no
2611	// row_valid check on A) never index past the valid Nout rows — pad rows are
2612	// zeroed (inert in the wgmma). Xt is NOT row-padded (the ring guards B rows via
2613	// row_valid → only valid Kin rows are read; pad cols are zero-filled in smem).
2614	__host__ __device__ __forceinline__ int64_t dec_dw_mpad(int Nout) {
2615	    return (int64_t)((Nout + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM) * wgs::kWgmmaAtomM;
2616	}
2617	__host__ __device__ __forceinline__ int64_t dec_dw_weight_t_elems(int Nout, int Kin, int64_t K) {
2618	    return (dec_dw_mpad(Nout) + (int64_t)Kin) * K;     // dYt[Mpad,K] + Xt[Kin,K]
2619	}
2620	// True only when the contiguous-transpose path is BOTH selected (stage==1) AND
2621	// actually wired (single-CTA dW, splitk==1 — the proof path; the split-K path
2622	// keeps the lambda gather). When false the scratch is 0-sized / unused and the
2623	// run-tile never reads dYt/Xt, so the workspace + control flow are byte-identical
2624	// to the scalar default.
2625	constexpr bool kDecDwTransposeActive = (kDecDwStage == 1) && (kDecDwSplitK == 1);
2626	
2627	__host__ __device__ __forceinline__ int64_t dec_dw_transpose_elems(int B, int T) {
2628	    if (!kDecDwTransposeActive) return 0;
2629	    const int64_t Kly = T, Khd = B;
2630	    int64_t e = 0;
2631	    // 8 layer weights (per layer: qkv 3d×d, attn_out d×d, ff0 dff×d, ff2 d×dff).
2632	    for (int li = 0; li < dec::kLayers; ++li) {
2633	        e += dec_dw_weight_t_elems(3 * dec::kD, dec::kD,   Kly);  // qkv
2634	        e += dec_dw_weight_t_elems(dec::kD,     dec::kD,   Kly);  // attn_out
2635	        e += dec_dw_weight_t_elems(dec::kDff,   dec::kD,   Kly);  // ff0
2636	        e += dec_dw_weight_t_elems(dec::kD,     dec::kDff, Kly);  // ff2
2637	    }
2638	    e += dec_dw_weight_t_elems(dec::kVocab, dec::kD, Khd);        // head (K=B)
2639	    return e;
2640	}
2641	
2642	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
2643	//
2644	// When SG_TUNED_DEC_DW_STAGE==1, `dwt_base` is the contiguous bf16 transpose
2645	// scratch (dec_dw_transpose_elems sized) and each spec's dYt/Xt/t_off are bound
2646	// to its packed sub-block (same running-offset walk as dec_dw_transpose_elems +
2647	// the host carve). On the scalar path pass dwt_base=nullptr → dYt/Xt stay null.
2648	__device__ __forceinline__ void dectc_build_dw_specs(
2649	        const DecActs& acts, int B, int T, DecDwSpec spec[kDecNumDwSpecs],
2650	        __nv_bfloat16* dwt_base);
2651	
2652	// Back-compat overload (scalar path / pre-existing call sites): no transpose
2653	// scratch. Forwards with dwt_base=nullptr so dYt/Xt are null and stage==0 runs
2654	// the proven lambda gather unchanged.
2655	__device__ __forceinline__ void dectc_build_dw_specs(
2656	        const DecActs& acts, int B, int T, DecDwSpec spec[kDecNumDwSpecs]) {
2657	    dectc_build_dw_specs(acts, B, T, spec, /*dwt_base=*/nullptr);
2658	}
2659	
2660	__device__ __forceinline__ void dectc_build_dw_specs(
2661	        const DecActs& acts, int B, int T, DecDwSpec spec[kDecNumDwSpecs],
2662	        __nv_bfloat16* dwt_base) {
2663	    // dec_layout offsets: see kDecOffsets. Per-layer 12-tensor block (li):
2664	    //   weight tidx = 2 + 12*li + {0,2,8,10}[kind] (in_w,out_w,ff0_w,ff2_w), bias +1.
2665	    //   head out.weight tidx = 2 + 12*L + 2, bias +1.
2666	    // At L=2 these reproduce the old wi {2,4,10,12,14,16,22,24} / bi {3,5,11,13,
2667	    // 15,17,23,25} and head {28,29} EXACTLY. 4*L layer specs + 1 head = kDecNumDwSpecs.
2668	    for (int s = 0; s < 4 * dec::kLayers; ++s) {
2669	        const int li = s / 4, kind = s % 4;
2670	        const int woff = (kind == 0) ? 0 : (kind == 1) ? 2 : (kind == 2) ? 8 : 10;
2671	        const int wi = 2 + 12 * li + woff;   // weight tensor index
2672	        const int bi = wi + 1;               // bias tensor index
2673	        DecDwSpec& sp = spec[s];
2674	        sp.K = T; sp.grad_off = kDecOffsets[wi]; sp.bias_off = kDecOffsets[bi];
2675	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
2676	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
2677	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
2678	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
2679	        sp.dY_bias = sp.dY;
2680	    }
2681	    DecDwSpec& hd = spec[4 * dec::kLayers];   // head spec (was spec[8] at L=2)
2682	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
2683	    hd.grad_off = kDecOffsets[2 + 12 * dec::kLayers + 2];           // out.weight (28 at L=2)
2684	    hd.bias_off = kDecOffsets[2 + 12 * dec::kLayers + 3];           // out.bias   (29 at L=2)
2685	    hd.dY_bias = hd.dY;
2686	
2687	    // CONTIGUOUS-TRANSPOSE bind (stage==1): pack each weight's dYt[Mpad,K] then
2688	    // Xt[Kin,K] into dwt_base via the SAME running-offset walk dec_dw_transpose_elems
2689	    // uses (so the kernel offsets == the host carve). On the scalar path (dwt_base
2690	    // null / stage==0) leave dYt/Xt null → dectc_dw_run_tile takes the lambda gather.
2691	    // #if-guarded (not if-constexpr): the dYt/Xt/t_off fields only EXIST when the
2692	    // macro is set, so the scalar default's struct + smem are byte-identical.
2693	#if SG_TUNED_DEC_DW_STAGE
2694	    if (kDecDwTransposeActive && dwt_base != nullptr) {
2695	        int64_t e = 0;
2696	        for (int s = 0; s < kDecNumDwSpecs; ++s) {
2697	            DecDwSpec& sp = spec[s];
2698	            sp.t_off = e;
2699	            sp.dYt   = dwt_base + e;                                  // [Mpad, K]

2700	            sp.Xt    = dwt_base + e + dec_dw_mpad(sp.Nout) * sp.K;    // [Kin,  K]
2701	            e += dec_dw_weight_t_elems(sp.Nout, sp.Kin, sp.K);
2702	        }
2703	    } else {
2704	        for (int s = 0; s < kDecNumDwSpecs; ++s) { spec[s].dYt = nullptr; spec[s].Xt = nullptr; spec[s].t_off = 0; }
2705	    }
2706	#else
2707	    (void)dwt_base;
2708	#endif
2709	}
2710	
2711	// ── CONTIGUOUS-TRANSPOSE PASS (SG_TUNED_DEC_DW_STAGE=1). Grid-cooperatively
2712	//    transpose each weight's dY[K,Nout] → dYt[Nout,K] and X[K,Kin] → Xt[Kin,K]
2713	//    into the packed dW-T scratch the specs bind. ELEMENT-OWNED (one writer per
2714	//    output element, fixed mapping) → DETERMINISTIC and A/A/A-safe; PURE bf16
2715	//    COPY (dYt[m,k]=dY[k,m] — NO arithmetic, NO reduction) → fp64-oracle parity
2716	//    is trivially preserved (the wgmma later consumes the SAME bf16 operand
2717	//    values in the SAME ascending-k order; only their MEMORY LAYOUT changed from
2718	//    transposed-strided gmem to K-contiguous gmem). Called by ALL CTAs after the
2719	//    backward writes dY/X to acts and BEFORE the dW phase, fenced by the existing
2720	//    B1 grid barrier (no new barrier). The total work is Σ_s (Nout_s+Kin_s)·K_s
2721	//    bf16 stores, touched ONCE per step and reused across every dW work item +
2722	//    split-K chunk of that weight. ──
2723	__device__ __forceinline__ void dectc_dw_transpose_operands(
2724	        const DecDwSpec spec[kDecNumDwSpecs], int cta, int nCTA) {
2725	#if SG_TUNED_DEC_DW_STAGE
2726	    if constexpr (!kDecDwTransposeActive) { (void)spec; (void)cta; (void)nCTA; return; }
2727	    const int tpb = blockDim.x;
2728	    const int64_t stride = (int64_t)nCTA * tpb;
2729	    const int64_t lane0  = (int64_t)cta * tpb + threadIdx.x;
2730	    for (int s = 0; s < kDecNumDwSpecs; ++s) {
2731	        const DecDwSpec& sp = spec[s];
2732	        if (sp.dYt == nullptr) continue;
2733	        const int64_t K = sp.K, Nout = sp.Nout, Kin = sp.Kin;
2734	        const int64_t Mpad = dec_dw_mpad(sp.Nout);
2735	        // dYt[m,k] = dY[k,m] for m<Nout; pad rows [Nout,Mpad) = 0 (inert — the
2736	        // ring reads A rows unguarded, so the row dim is padded to a 64-atom
2737	        // boundary). Linear out-index i = m*K+k over the FULL padded [Mpad,K).
2738	        const int64_t ndy = Mpad * K;
2739	        for (int64_t i = lane0; i < ndy; i += stride) {
2740	            const int64_t m = i / K, k = i % K;
2741	            sp.dYt[i] = (m < Nout) ? sp.dY[k * Nout + m] : __float2bfloat16(0.f);
2742	        }
2743	        // Xt[n,k] = X[k,n], n in [0,Kin), k in [0,K). Linear out-index i = n*K+k.
2744	        // (No row pad: the ring guards B rows via row_valid → pad N-tile cols are
2745	        // zero-filled in smem, never read from Xt.)
2746	        const int64_t nx = Kin * K;
2747	        for (int64_t i = lane0; i < nx; i += stride) {
2748	            const int64_t n = i / K, k = i % K;
2749	            sp.Xt[i] = sp.X[k * Kin + n];
2750	        }
2751	    }
2752	#else
2753	    (void)spec; (void)cta; (void)nCTA;   // scalar default: no transpose pass
2754	#endif
2755	}
2756	
2757	// ── dW M-atom INTERLEAVE group width (task #13 H3). A dW output "tile" (work
2758	//    item) owns a GROUP of up to kDecDwIL consecutive m64 atoms instead of one,
