465	// ════════════════════════════════════════════════════════════════════════
466	//  bf16 WEIGHT PRE-STAGE (reg-pressure campaign C1 + cp.async-ring blocker (a)).
467	//  The fwd/dX GEMMs' B operand was the fp32 params blob CONVERTED ON READ
468	//  (__float2bfloat16 inside the staging accessor). That conversion web is the
469	//  measured marginal register demand of the K-loop (the pure-bf16 dW path
470	//  allocates spill-free at the same accumulator width while the fp32-read
471	//  fwd/dX paths spill ~2.2 KB when isolated), and it is the documented blocker
472	//  (a) of the cp.async/TMA ring: an async copy cannot convert, so the dominant
473	//  operand could not stream. Fix: convert ONCE per step into a bf16 weight
474	//  cache carved from the workspace, and stage the GEMM B operand from the
475	//  cache. cache[i] = __float2bfloat16(params[i]) is the IDENTICAL deterministic
476	//  per-element rounding the on-read path performed -> every GEMM consumes
477	//  BIT-IDENTICAL operand values; numerics/parity/A-A-A are unchanged BY
478	//  CONSTRUCTION (pure caching of a pure function; no reorder, no reassociation).
479	//
480	//  Only the 8 per-layer GEMM weight matrices (in_w/out_w/ff0_w/ff2_w x layers)
481	//  are cached: they are the ONLY fp32->bf16 on-read GEMM operands (the head
482	//  runs scalar fp32 per the oracle; embeddings/biases/LN are scalar fp32; the
483	//  dW GEMM operands are bf16 acts already). All sizes derive from the layout
484	//  constants -- no problem-specific hardcoding; the bench layout scales it.
485	//
486	//  C1-T (RING): a SECOND section of the cache holds the same 8 matrices
487	//  TRANSPOSED (W^T [Kin,Nout]). The dX GEMM reads W transposed; from the
488	//  row-major cache that staging is a k-stride 2-byte gather, which no 4/8/16B
489	//  cp.async can express (the same structural shape as ring blocker (b)).
490	//  Staging dX's B operand from W^T instead makes its tile rows K-CONTIGUOUS,
491	//  so the cp.async double-buffered ring streams BOTH fwd and dX weight
492	//  operands. WT[r,c] == W-cache[c,r] bit-identically (same fp32 element, same
493	//  deterministic rounding, written by exactly one thread) -> operand values,
494	//  parity and A/A/A are unchanged by construction. Cost: the cache doubles
495	//  (1.57 MB at d=128, 101 MB at d=1024 -- workspace headroom verified at both).
496	// ════════════════════════════════════════════════════════════════════════
497	struct DecWBf {
498	    const __nv_bfloat16* in_w[dec::kLayers];    // [3d, d]  per layer
499	    const __nv_bfloat16* out_w[dec::kLayers];   // [d, d]   per layer
500	    const __nv_bfloat16* ff0_w[dec::kLayers];   // [dff, d] per layer
501	    const __nv_bfloat16* ff2_w[dec::kLayers];   // [d, dff] per layer
502	    // ── C1-T (RING section): the SAME four matrices stored TRANSPOSED, W^T
503	    //    [Kin, Nout] row-major. WT[r,c] == W-cache[c,r] BIT-IDENTICAL (the same
504	    //    __float2bfloat16 of the same fp32 element, stored twice). Purpose: the
505	    //    dX GEMM's B operand reads W TRANSPOSED (srcB(n=kin,k=out) = W[out,kin],
506	    //    a k-stride-Kin 2-byte gather the cp.async ring cannot stream — the same
507	    //    structural shape as ring blocker (b)). Staging from W^T instead makes
508	    //    the dX B-tile rows K-CONTIGUOUS (16B-chunkable), unblocking the ring on
509	    //    the dX path with UNCHANGED operand values → numerics/parity/A-A-A
510	    //    identical by construction. ──
511	    const __nv_bfloat16* in_wT[dec::kLayers];   // [d, 3d]  per layer
512	    const __nv_bfloat16* out_wT[dec::kLayers];  // [d, d]   per layer
513	    const __nv_bfloat16* ff0_wT[dec::kLayers];  // [d, dff] per layer
514	    const __nv_bfloat16* ff2_wT[dec::kLayers];  // [dff, d] per layer
515	};
516	constexpr int64_t kWbfInW        = (int64_t)3 * dec::kD * dec::kD;
517	constexpr int64_t kWbfOutW       = (int64_t)dec::kD * dec::kD;
518	constexpr int64_t kWbfFf0W       = (int64_t)dec::kDff * dec::kD;
519	constexpr int64_t kWbfFf2W       = (int64_t)dec::kD * dec::kDff;
520	constexpr int64_t kWbfLayerElems = kWbfInW + kWbfOutW + kWbfFf0W + kWbfFf2W;
521	constexpr int64_t kWbfTotalElems = (int64_t)dec::kLayers * kWbfLayerElems;
522	// Full cache: straight section [kWbfTotalElems] + transposed section (C1-T,
523	// same element count — every matrix size is a multiple of 8 so both sections
524	// and every per-matrix base stay 16B-aligned for the cp.async ring).
525	constexpr int64_t kWbfCacheElems = 2 * kWbfTotalElems;
526	// Workspace floats the cache occupies (bf16 elems -> float units, rounded up).
527	__host__ __device__ __forceinline__ int64_t dec_wbf_floats() {
528	    return (kWbfCacheElems + 1) / 2;
529	}
530	__device__ __forceinline__ DecWBf dec_wbf_bind(const __nv_bfloat16* c) {
531	    DecWBf wb;
532	    #pragma unroll
533	    for (int li = 0; li < dec::kLayers; ++li) {
534	        const __nv_bfloat16* b = c + (int64_t)li * kWbfLayerElems;
535	        wb.in_w[li]  = b;
536	        wb.out_w[li] = b + kWbfInW;
537	        wb.ff0_w[li] = b + kWbfInW + kWbfOutW;
538	        wb.ff2_w[li] = b + kWbfInW + kWbfOutW + kWbfFf0W;
539	        // transposed section (C1-T): same per-layer/per-matrix offsets, based
540	        // kWbfTotalElems further in (element counts identical per matrix).
541	        const __nv_bfloat16* t = b + kWbfTotalElems;
542	        wb.in_wT[li]  = t;
543	        wb.out_wT[li] = t + kWbfInW;
544	        wb.ff0_wT[li] = t + kWbfInW + kWbfOutW;
545	        wb.ff2_wT[li] = t + kWbfInW + kWbfOutW + kWbfFf0W;
546	    }
547	    return wb;
548	}
549	// Grid-strided fp32->bf16 convert of the 8 matrices into the cache. Element-
550	// owned (each cache index written by exactly one thread), no atomics ->
551	// deterministic. Caller fences with the existing grid barrier before any GEMM
552	// reads the cache (P0->B0; the SAM re-convert gets its own barrier). The
553	// kDecOffsets index of [in_w,out_w,ff0_w,ff2_w] for layer li is {2,4,10,12} +
554	// 12*li (the 12-tensors-per-layer stride of the generated layout -- the same
555	// indices dectc_build_dw_specs walks).
556	__device__ __forceinline__ void dectc_wbf_convert(
557	        const float* __restrict__ params, __nv_bfloat16* __restrict__ cache,
558	        int cta, int nCTA) {
559	    const int64_t stride = (int64_t)nCTA * blockDim.x;
560	    for (int64_t i = (int64_t)cta * blockDim.x + threadIdx.x;
561	         i < kWbfCacheElems; i += stride) {
562	        // Section split: [0, kWbfTotalElems) = straight copies; the tail is the
563	        // C1-T TRANSPOSED section (the dX ring's B operand). Both sections are
564	        // element-owned (one writer per cache index) -> deterministic.
565	        const bool   tr = (i >= kWbfTotalElems);
566	        const int64_t ii = tr ? (i - kWbfTotalElems) : i;
567	        const int   li = (int)(ii / kWbfLayerElems);
568	        const int64_t r = ii % kWbfLayerElems;
569	        int wi; int64_t off, nout, kin;
570	        if      (r < kWbfInW)                       { wi = 2;  off = r;                                  nout = 3 * dec::kD; kin = dec::kD;   }
571	        else if (r < kWbfInW + kWbfOutW)            { wi = 4;  off = r - kWbfInW;                        nout = dec::kD;     kin = dec::kD;   }
572	        else if (r < kWbfInW + kWbfOutW + kWbfFf0W) { wi = 10; off = r - kWbfInW - kWbfOutW;             nout = dec::kDff;   kin = dec::kD;   }
573	        else                                        { wi = 12; off = r - kWbfInW - kWbfOutW - kWbfFf0W;  nout = dec::kD;     kin = dec::kDff; }
574	        // straight: source element `off` of W [Nout,Kin]. transposed: `off` is
575	        // element (rr,cc) = (off/Nout, off%Nout) of W^T [Kin,Nout]; its source is
576	        // W[cc,rr] = element cc*Kin + rr — the SAME fp32 through the SAME
577	        // deterministic rounding, so WT[rr,cc] is bit-identical to W-cache[cc,rr].
578	        const int64_t src = tr ? ((off % nout) * kin + (off / nout)) : off;
579	        cache[i] = __float2bfloat16(params[(int64_t)kDecOffsets[wi + li * 12] + src]);
580	    }
581	}
