601	        const int mn = i / wgs::kWgmmaAtomK;
602	        const int k  = i % wgs::kWgmmaAtomK;
603	        const int dst = (k >> 3) * (MN * 8) + mn * 8 + (k & 7);
604	        smem_tile[dst] = src(mn, kbase + k);
605	    }
606	}
