// ── kTPComm correctness model (the in-kernel device-NVSHMEM TP DATA PATH).
//    The host (tuning/_tp8_run.py) gives EVERY rank the FULL replicated param
//    blob (NOT a pre-packed per-rank shard) and performs NO host-side gradient
//    sync between steps; the kernel updates params in place. For all 8 ranks to
//    stay BIT-CONSISTENT step over step (the cross_rank_agree + descends gate)
//    every rank must apply the IDENTICAL FULL param update ⇒ compute the
//    IDENTICAL FULL gradient. A Megatron weight-shard (each rank a distinct
//    dW slice) would diverge the replicated params unless a full-weight grad
//    all-reduce is added — which the tiny tile-sized symmetric heap cannot carry
//    without a chunked whole-matrix reduce (out of the 8×H100 window budget).
//
//    So the kTPComm path computes EVERY projection FULL-WIDTH REPLICATED (the
//    same math as SingleGPU, incl. attention at the full kHeads=25 — this also
//    removes the kHeads%TP!=0 / Dloc==Hloc·kDhead invariant violation that was
//    bug B), and the four reduce points (out_proj ①, ff2 ②, ff0-dX ②',
//    in_proj-dX ①') still drive the REAL device-NVSHMEM all-reduce over NVLink:
//    each rank publishes (full_result / P) and the ascending-pe fixed-order sum
//    of P identical copies reconstructs full_result. This genuinely exercises
//    the NvshmemTransport peer()/nvshmem_ptr NVLink reads + the team barrier,
//    is a mathematical identity (so the result + grads stay full + replicated +
//    identical on every rank), and writes ONLY full-width buffers (matching
//    dec_acts_bind) — eliminating the out-of-bounds shard-width writes (bug C).
//    A future genuine weight-shard needs the host to pre-pack per-rank shards
//    AND a whole-weight grad all-reduce; that is scoped, not done here.
const float kTpInvP = Par::kTPComm ? (1.0f / (float)tr.n_pes()) : 1.0f;
for (int li = 0; li < dec::kLayers; ++li) {
    const DecWeights::Layer& L = w.layer[li];
    const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
    // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
    // FULL-WIDTH on kTPComm (replicated; see the correctness model above).
    const int qkv_nout = 3 * dec::kD;
    dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, wb.in_w[li], sc.qkv[li], dec::kD, qkv_nout, sA, sB, pipeBars);
    __syncthreads();
    // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
    // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
    for (int idx = threadIdx.x; idx < nrows * qkv_nout; idx += blockDim.x) {
        const int j = idx % qkv_nout;
        float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
        sc.qkv[li][idx] = __float2bfloat16(v);
    }
    __syncthreads();
    // attention → ctx (work fp32) + attn[li] weights. FULL-WIDTH on BOTH paths
    // (the SAME dectc_attn_fwd_tile): all kHeads heads from the full qkv. ctx is
    // [nrows,d]; the out_proj below is REPLICATED (no row-shard) on kTPComm.
    dectc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
    // ctx bf16 → X_ctx[li] (out_proj input + its dW operand). Full width.
    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
        const int r = idx / dec::kD, j = idx % dec::kD;
        acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.work[(int64_t)r * dec::kD + j]);
    }
    __syncthreads();
    // a = X_ctx @ out_w^T (+ out_b)  (N=d, K=d). fp32 → work. FULL-WIDTH on both
    // paths; on kTPComm the full result is routed through a NVLink all-reduce of
    // (a/P) so the device-NVSHMEM path is exercised while a stays full+identical.
    dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * dec::kD, wb.out_w[li],
                                        sc.work, dec::kD, dec::kD, sA, sB, pipeBars);
    __syncthreads();
    if constexpr (Par::kTPComm) {
        // ① publish (a/P) to the symmetric slot → ascending-pe Σ → a (identity).
        float* pub = tr.local(slot_pub);
        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
            pub[idx] = sc.work[idx] * kTpInvP;
        tr.rendezvous(bar);                                  // publish visible (NVLink)
        ::sg::fused::sm90::tp::tp_allreduce_sum_fixed_order(
            tr, slot_pub, sc.work, (int64_t)nrows * dec::kD, threadIdx.x, blockDim.x);
        tr.rendezvous(bar);                                  // slot reusable
        __syncthreads();
    }

